values
  ('3891b9a9-bbf4-47cc-89ea-207390eb438f', 'b5219ed4-4761-4219-843f-139b8050d861', null, 'topic'::public.curated_course_node_type, 'Dynamic System Modeling Across Physical Domains', 'This opening topic teaches students to translate real mechanical, electrical, thermal, and fluid systems into mathematical models. The point is to see control design as a response to system behavior, not as a formula applied after the fact.', 0),
  ('04afe3a8-f863-49cf-9a08-41123676f419', 'b5219ed4-4761-4219-843f-139b8050d861', '3891b9a9-bbf4-47cc-89ea-207390eb438f', 'subtopic'::public.curated_course_node_type, 'Modeling assumptions', 'Students learn to define boundaries, inputs, outputs, states, and simplifications before writing equations.', 0),
