  ('5026e83a-3ec6-4640-adad-ed8d86512181', 'b5219ed4-4761-4219-843f-139b8050d861', null, 'topic'::public.curated_course_node_type, 'Laplace Transforms and Solution of Dynamic Responses', 'Laplace methods turn differential equations into algebraic relationships that are easier to analyze and design around. Students learn the transform tools needed for transfer functions, block diagrams, and feedback analysis.', 1),
