  ('d85c246f-6bbc-4897-ae7d-4325f8661b7c', 'b5219ed4-4761-4219-843f-139b8050d861', null, 'topic'::public.curated_course_node_type, 'Transfer Functions, Poles, Zeros, and System Representation', 'Transfer functions summarize how linear time-invariant systems map inputs to outputs. Students learn to interpret poles and zeros as fingerprints of dynamics, stability, and response shape.', 2),
